#!/usr/bin/env python3
"""Builds .ufo/waves/round-75/w1-spec.json (tabi round 75, one v1 wave of 11 seats).
Reads the freeze facts (D, pins, nonce, PRE) from committed files so nothing is hand-transcribed."""
import json, pathlib, re
L = '/home/vgpnk/Projects/shokunin/tabi-shokunin'
R = L + '/.ufo/waves/round-75'
W = R + '/w1'
SC = '/fast/scratch/hyaku/tabi-r75'
DIRECTIVE = pathlib.Path('/home/vgpnk/.agents/skills/godspeed/directive.md').read_text()
FZ = pathlib.Path(R + '/freeze.txt').read_text()
pins = dict((p, h) for h, p in re.findall(r'^([0-9a-f]{64})  (\S+)$', FZ, re.M))
PIN_D = pins['scripts/chrome-cdp-dragdrop-round75.mjs']
PIN_C = pins['scripts/check-dragdrop-r75.mjs']
D = pathlib.Path(R + '/scored/digests-commit.txt').read_text().split()[0]
D12 = D[:12]
NA = 'tabi-r75-l1-' + D12
NB = 'tabi-r75-exec1-' + D12
EV = L + '/corpus/evidence/round75/chromium-drag-intercept/receipt.json'
C1D = R + '/controls/c1'
PRE = [L + '/' + l.strip() for l in pathlib.Path(C1D + '/prior-set.txt').read_text().splitlines() if l.strip() and not l.startswith('#')]
PP = ' '.join('--prior ' + p for p in PRE)
DEG = ' '.join(f'--laundered {C1D}/degenerate-{k}.receipt.json' for k in ['native-mouse', 'no-intercept', 'script-events'])
STATUS = pathlib.Path(R + '/scored/status-at-dispatch.txt').read_text().strip()

context = f"""# Target
Tabi round 75, one v1 wave w1. L1 TabiR75 holds the planner seat and is the sole integration owner. Lane {L}; base c19a520fdfa574a5c082b09130b7dbfcdd1e99eb. Claim FROZEN in {R}/claims.json; instrument digests in {R}/freeze.txt, digests commit D = {D}. Never propose amending the predicate, counter, pins, priors, thresholds or kill rule; attack them.
C1 coverage, NEW capability chromium-drag-intercept-linux: CDP Input.setInterceptDrags + Input.dispatchDragEvent + the Input.dragIntercepted event on Chromium 155.0.8059.84 headless (/usr/bin/chromium), loopback fixture with a draggable <div id=src>, an accepting drop zone <div id=dz> and a non-accepting zone <div id=nz>, 15 legs (intercept-on, press, move-start -> one dragIntercepted, move-far, enter/over/drop on dz replaying the intercepted data, release, external enter+drop on nz -> dragleave, external enter on dz, dragCancel, a drop after cancel -> nothing, a dragLeave type -> -32602). Driver {L}/scripts/chrome-cdp-dragdrop-round75.mjs (sha256 {PIN_D}); counter {L}/scripts/check-dragdrop-r75.mjs (sha256 {PIN_C}, 146 checks; REQUIRES --expect-driver-sha256, --expect-nonce and >= 1 --prior; its fixture-hash check reads the pinned driver BESIDE the counter file; its replay-event-timeline is an event-time multiset match (>= 0.5 of events within 0.05 ms) OR a >= 50 ms gap multiset match (>= 0.75 of gaps), and its output records priorSet); battery {L}/scripts/negatives-dragdrop-r75.mjs (REQUIRES the three --laundered degenerate receipts; --first-failure is for kill-power mutant runs only); kill power {C1D}/kill-power-r75.mjs (a crashed battery is never a kill).
PRE (the 16 committed pre-freeze receipts = the schema enumeration in {C1D}/prior-set.txt) as arguments: {PP}
Laundered degenerates as arguments: {DEG}
Predicate C1-DRAGINTERCEPT-R75: (a) L1 post-D scored run, nonce {NA}, counter exit 0 clean (146) with PRE priors, receipt {EV}; (b) independent cold run by R75Exec1, nonce {NB}, counter clean with PRE priors plus the (a) receipt as 17th prior; (c) battery exit 0 AND kill power holds on the (a) receipt; (d) capability row 0->1 + note {L}/corpus/knowledge/chromium-drag-intercept-runtime-round-75.md citing S196-S200.
STATUS AT DISPATCH (measured by the L1, committed in {R}/scored/): {STATUS}
Pre-freeze evidence: counter, battery and kill power over all 9 smoke receipts ({C1D}/prefreeze-summary.json); do-nothing/forgery/limit controls {C1D}/controls-summary.json; honest-pair timeline measurement {R}/lesson-proof/timeline-honest-pairs.json; pre-freeze defects {R}/lesson-proof/.
New sources this round: S196-S200 (Input.pdl, input_handler.cc, web_frame_widget_impl.cc, drag_controller.cc, data_transfer.cc; Chromium tag 155.0.8059.84), staged in {R}/sources/ with FETCH.txt (rows in {L}/corpus/SOURCES.md). Note {L}/corpus/knowledge/chromium-drag-intercept-runtime-round-75.md. Lesson {L}/corpus/lessons/round-75.md.
Prior closures to learn from: {L}/corpus/lessons/round-74-verifier-spotcheck.md, round-73-verifier-spotcheck.md, round-72-verifier-spotcheck.md.
# Bounds
All paths absolute. Write ONLY inside your own {W}/<your name>/ directory (reports, receipts, proposed files); never production, lane-root, fleet or sibling files. Every `Report:` trailer path is relative to {L} -- write it at {L}/<that path>, NEVER under the fleet root /home/vgpnk/Projects/shokunin. No git/jj mutations, commits or pushes anywhere; read-only git only (git -C <repo> show/log/rev-parse/status/grep). Any fixture repo: D=$(mktemp -d -p {SC}/<your name>) && git -C "$D" init -q, every later call names -C "$D" and you assert git -C "$D" rev-parse --show-toplevel equals "$D" first. One integration owner (the L1). No delegation, no swarms, no task calls (an executor may spawn at most one read-only labrat probe). Never mutate host sysctls, services or any host path outside your scratch (/boot, /etc, /usr, /var are read-only to you). Scratch: every clone, work dir and fixture lives under {SC}/<your name>/ (mkdir -p; pass it explicitly as TMPDIR/--work/--scratch; /tmp only for files under 50 MB); delete your scratch dir before you yield (trap 'rm -rf -- "$S"' EXIT), copying receipts into your wave dir first. The host is heavily loaded (load average ~300 on 32 cores): run long jobs with --jobs <= 6.
Tooling: you may install or upgrade tools that help the task -- first read /home/vgpnk/.omp/agent/RULES.md (official channels, update-safety gate; record tool/version/channel/reason). pacman guard: all pacman transactions are PAUSED host-wide; install via uv tool / npx / an official binary in ~/.local/bin, never -Sy/-Syu/-U/-R. Record every install in your report.
# Output
Your report's first line is one verdict word (HOLDS, FALSIFIED, FINDINGS, CONFIRMED, REFUTED, DONE or BLOCKED). Every claim in it carries a command and its exit code or a path:line. Unrun = not passed."""

def item(name, role, axes, milestone, body):
    return {"name": name, "role": role, "axes": axes, "milestone": milestone,
            "prompt": "/skill:godspeed\n\n" + DIRECTIVE + "\n# Assignment\n" + body.strip() + f"\n\nWrite {W}/{name}/report.md (first line: verdict word), plus any receipts beside it."}

items = [
 item("R75Exec1", "executor", ["coverage"], "Predicate leg (b): independent cold run, plus independent re-run of leg (c)", f"""
Check the pinned digests first: sha256sum every file listed in {R}/freeze.txt and compare; report each.
Leg (b): run the pinned driver ONCE cold: mkdir -p {SC}/R75Exec1/d && TMPDIR={SC}/R75Exec1/d node {L}/scripts/chrome-cdp-dragdrop-round75.mjs --scratch {SC}/R75Exec1/d --out {W}/R75Exec1/receipt.json --nonce {NB} --http-port <free p1> --cdp-port <free p2> ; capture rc on the very next line. Only if that rc is 2 AND no receipt was written (usage refusal before launch) may you re-run with new ports; any receipt written is final. Then node {L}/scripts/check-dragdrop-r75.mjs --receipt {W}/R75Exec1/receipt.json --expect-driver-sha256 {PIN_D} --expect-nonce {NB} {PP} --prior {EV} --json > {W}/R75Exec1/counter.json ; rc on the next line.
Leg (c), independently, on the L1's scored receipt: node {L}/scripts/negatives-dragdrop-r75.mjs --real {EV} --expect-driver-sha256 {PIN_D} --expect-nonce {NA} {PP} {DEG} --work {SC}/R75Exec1/n --jobs 6 --json > {W}/R75Exec1/negatives-a.json ; rc. Then the battery on YOUR receipt (--real {W}/R75Exec1/receipt.json --expect-nonce {NB}, priors PRE plus --prior {EV}) > {W}/R75Exec1/negatives-b.json ; rc. Then node {C1D}/kill-power-r75.mjs --lane {L} --real {EV} --expect-driver-sha256 {PIN_D} --expect-nonce {NA} {PP} {DEG} --work {SC}/R75Exec1/k --out {W}/R75Exec1/kill-power-a.json --jobs 5 ; rc. Report: driver rc, counter verdict/checkCount/findings/priorSet length, battery passed/cases/failed for both receipts, kill power forceTrue/semantic/survivors/crashed/holds. State plainly whether legs (b) and (c) hold as frozen."""),
 item("R75Exec2", "executor", ["coverage", "calibration"], "Post-freeze repetition red rate and honest-pair replay margin", f"""
Run the pinned driver 3 times cold (nonces tabi-r75-exec2-<n>-<8 hex>, own free ports, scratch {SC}/R75Exec2/d<n>, receipts {W}/R75Exec2/d<n>.receipt.json). On each: counter (--expect-driver-sha256 {PIN_D} --expect-nonce <its nonce> {PP} --prior {EV}) and battery (same pin/nonce/priors, --work {SC}/R75Exec2/w<n>, {DEG}, --jobs 6). Tabulate per-check counter red rate and per-case battery failure rate over these 3 receipts plus the 9 pre-freeze smokes (their results are {C1D}/pf-smoke<n>.counter.json / .battery.json). Run node {R}/lesson-proof/timeline-honest-pairs.mjs <your 3 receipts> {EV} and report maxAbs, maxGap, honestPairsRefused and minOwnGaps over all 17 honest receipts against the counter thresholds (0.5 events / 0.75 gaps, >= 6 gaps): is any honest pair within one gap match of refusal?"""),
 item("R75Review1", "reviewer", ["coverage"], "False greens in check-dragdrop-r75.mjs", f"""
Review {L}/scripts/check-dragdrop-r75.mjs at its frozen bytes (sha256 {PIN_C}). Craft receipts in your scratch from {EV} and the PRE receipts (never edit the scripts) and score them with the pinned counter (run it from {L}/scripts so the pinned driver sits beside it). Priority: (1) receipt-content false greens: fields the laws do not read (custom on non-drop events, items, buttons on pointer events, the stateAfter keys, cdpResult), the per-leg view collapsing distinct values ('|'-joined DataTransfer view: can two different event field sets render the same string?), events of an unknown target, duplicated events with renumbered seq inside an empty leg, sentData vs send-log data consistency; (2) the replay checks: any relabel of a PRE receipt that is accepted while changing fewer event times than the declared limit sentence in {R}/claims.json says is needed (insert/delete an event, move only events inside one leg, exploit the greedy multiset matching order, the >= 6 gaps floor, the 50 ms gap boundary); (3) the producer binding: can a receipt whose dragIntercepted event was never received (afterSendId forged, data copied from the plan) pass? Report each finding with the crafted file, the counter command, its exit code and finding ids, and whether the declared limit already names it."""),
 item("R75Review2", "reviewer", ["coverage", "calibration"], "Battery and kill-power review: isolation, first-failure path, crash classification", f"""
Review {L}/scripts/negatives-dragdrop-r75.mjs and {C1D}/kill-power-r75.mjs at their frozen bytes ({R}/freeze.txt). (1) QUALITY 135 ({L}/corpus/QUALITY.md item 135): re-run the battery on 3 of the 9 PRE smokes of your choice (priors = the other 15 PRE receipts, --expect-nonce from {C1D}/smoke<n>.args.txt first field, the three --laundered degenerates, --jobs 6) and compare with the committed pf-smoke<n>.battery.json. Is any refusal case's mutation relative to an honest value such that it could fall inside a tolerance on some honest receipt? (2) Isolation: can any refusal case pass with its expected id absent, or does an alsoAllowed list hide a co-firing defect (the per-leg cases allow every law id)? Does any must-accept case accept a distinguishable forgery? (3) The --first-failure fast path: can a mutant be scored killed when the battery stopped for a reason unrelated to the mutant (e.g. a flaky case, a timeout kill of the counter at 60 s under load), and can a survivor be scored crashed? Build the cheapest such counterexample in your scratch and run kill power on a copy. (4) Does kill power still score a crashed battery as crashed (craft a counter copy that throws) ? Report each with commands, exit codes and the result files."""),
 item("R75Review3", "reviewer", ["calibration"], "Conformance: freeze ordering, pins, nonce derivation, prior-set enumeration, before->after", f"""
Read-only conformance review of round 75's C1 against its own rules. (1) Ordering: git -C {L} log --format='%H %ci %s' c19a520f..master -- .ufo/waves/round-75 scripts corpus SCORECARD.md: the pre-freeze commit precedes the claims.json commit, which precedes D {D} (freeze.txt), which precedes the scored receipt commit. (2) Pins: sha256 of every file named in freeze.txt at D and at the current tip equal the recorded digests. (3) Nonce: the scored receipt's nonce equals {NA} and no file committed at or before D contains that string (git -C {L} grep at D). (4) QUALITY 140: run git -C {L} grep -l '"schema": "tabi-chrome-cdp-dragdrop-r75"' <freeze parent> -- '*.json' and compare with {C1D}/prior-set.txt line by line; then the same at D and at the tip: does any committed receipt of the schema lie outside PRE (the scored receipt and wave receipts are expected after D; name each)? (5) Before->after: re-run the before commands in claims.json at base c19a520f (git show) and confirm counts; re-run the (a) counting command at the tip. (6) QUALITY 130/131/133/135/137/139: check each against the committed pre-freeze evidence. Report each item PASS/FAIL with the command and output."""),
 item("R75Critic", "critic", ["coverage"], "Falsify the claim: do-nothing reach, forgeries, honest limits, sourced field", f"""
Attack {R}/claims.json. (1) Could a do-nothing or look-alike producer meet legs (a)-(c) as frozen? Build the cheapest forgery you can (a relabel of a PRE receipt with minimal re-timing, a synthesised receipt, a receipt from a modified driver run with the pin field rewritten, a script-driven page that fakes trusted drag events, a native mouse drag with the send log rewritten) and score it with the pinned counter using the frozen arguments; say whether each forgery is inside or outside the declared limit. (2) Is the limit sentence complete and honest relative to what the counter reads (count the minimum number of event times a forger must change; is 'more than half of event times and more than a quarter of gaps' exact, or can fewer escape)? (3) Is C1 named by the surface it moves (coverage: a capability row for a command family no tabi row covers; check SCORECARD.md and corpus/knowledge at base c19a520f), and is the 'sourced' field true: do S196-S200 (staged {R}/sources/) say what the note and the counter laws claim, line by line? (4) Is the priorSet sentence true against the repository at the freeze parent?"""),
 item("R75Mut1", "mutation-tester", ["coverage"], "Semantic mutants beyond the 40 frozen ones", f"""
Copy {L}/scripts/check-dragdrop-r75.mjs, negatives-dragdrop-r75.mjs and chrome-cdp-dragdrop-round75.mjs (the counter needs the driver beside it) to {SC}/R75Mut1/s/. Generate >= 25 single-edit semantic mutants of the counter that are NOT among the 40 in {C1D}/kill-power-r75.mjs and do not simply force a check true: operators, tolerances (TOL, GAP_MIN, FRAC, GAP_FRAC, the >= 6 floor), every/some, off-by-one in leg windows and seq, dropped conjuncts in typed()/dtFields(), allow-list EXPRS entries, the greedy multiset matcher, the drop-acceptance filter, the cancel index, the mask table, the coordinate-law exemptions, SHAPE literals. For each, run the battery COPY beside it: node <copy>/negatives-dragdrop-r75.mjs --real {EV} --expect-driver-sha256 {PIN_D} --expect-nonce {NA} {PP} {DEG} --work {SC}/R75Mut1/w<i> --jobs 6 --json ; killed = exit 1 with a parsable summary whose failed list is non-empty. For every survivor, write a receipt (an acceptance witness) that the mutant accepts and the frozen counter refuses, or argue it is equivalent. Report a table: mutant, edit, battery exit, failed cases, survivor witness path."""),
 item("R75Scout", "scout", ["coverage", "depth"], "Independently open S196-S200 and locate the open mechanism", f"""
Independently fetch, this session, base64 ?format=TEXT, decode: https://chromium.googlesource.com/chromium/src/+/refs/tags/155.0.8059.84/<path>?format=TEXT for third_party/blink/public/devtools_protocol/domains/Input.pdl, content/browser/devtools/protocol/input_handler.cc, third_party/blink/renderer/core/frame/web_frame_widget_impl.cc, third_party/blink/renderer/core/page/drag_controller.cc, third_party/blink/renderer/core/clipboard/data_transfer.cc. Record access time, sha256 and line count, and `cmp` each with the L1-staged copy in {R}/sources/. Locate and quote (<= 25 words each, with line numbers) the lines cited in {L}/corpus/SOURCES.md rows S196-S200 and in the note {L}/corpus/knowledge/chromium-drag-intercept-runtime-round-75.md. Then the open mechanism the note marks as measured only: why does a `drag` event fire on the source before dragenter (enter-dz) and before dragover (drop-dz) but not in over-dz? Open third_party/blink/renderer/core/input/event_handler.cc and mouse_event_manager.cc at the same tag and locate the dispatch of `drag` during UpdateDragAndDrop / PerformDragAndDrop (quote with line numbers, or say it is not there). Propose at most two new SOURCES rows in the lane's 11-column shape (in your report only)."""),
 item("R75Connector", "connector", ["adjacency"], "Sibling overlap scan for drag-and-drop ground", f"""
Scan sibling lanes under /home/vgpnk/Projects/shokunin/*-shokunin (read-only) for knowledge, SOURCES rows or scripts overlapping tabi's r75 ground: setInterceptDrags, dispatchDragEvent, dragIntercepted, DragData, dragOperationsMask, DataTransfer, getData, dropEffect, effectAllowed, dragstart/dragenter/dragover/drop/dragend, DragTargetDrop, CancelDrag, and the five source files of S196-S200. For each hit: lane, path:line, quote <= 25 words, whether it is contested scope against tabi's PROVINCE ({L}/PROVINCE.md) and whether it is a duplicate-URL risk for S196-S200 (sources-census W04/E04). Output a table and a one-line verdict (overlap none / adjacent / contested)."""),
 item("R75Scribe", "scribe", ["depth"], "Independent re-derivation of the r75 note and lesson Gate", f"""
Read {L}/corpus/knowledge/chromium-drag-intercept-runtime-round-75.md, {L}/corpus/lessons/round-75.md and the staged sources in {R}/sources/. Independently re-derive (with node/python over the receipts, show the command) the per-leg event sequences, defaultPrevented, DataTransfer view, coordinates and state-after over the 9 PRE smokes, the 4 probes and the (a) receipt {EV}, and check every row of the note's measured table and every quoted line/line number in the note and lesson against your derivation and the sources. Draft, in {W}/R75Scribe/, (1) note-review.md: agree/disagree per statement with evidence and proposed wording fixes; (2) gate-review.md: per S196-S200 row, does the lesson's quote occur at the stated line, is it <= 25 words; plus one admit and one reject decision a non-author closure could spot-check."""),
 item("R75Revenger", "revenger", ["calibration"], "Fresh-start audit: does r75 repeat a rejected or routed root failure?", f"""
Read the non-author spotchecks {L}/corpus/lessons/round-60-, round-61-, round-62-, round-71-, round-72-, round-73- and round-74-verifier-spotcheck.md and the MANIFEST closure rows for tabi r60-r74 (/home/vgpnk/Projects/shokunin/MANIFEST.json, read-only; rounds array entries with lane tabi). For each root failure (K7 no-regression conjunct; frozen header rejected; post-scoring recorder/interface changes; M5 AND->OR survivor; contradictory duplicate/fabricated dispositions; r71 leg-b relabel leak; r72 relative battery case and replay hole; r73 prior-set limit and 1e-12 timeline escape; r74 probe receipts outside PRE, count-change near-match escape, crash-as-kill, the four r74 routed defects), determine from committed r75 bytes whether round 75 repeats it, closes it, or leaves it open: cite path:line or a command and its output. Also check the SCORECARD/SHONEN self-assessment against observed repo state (calibration: count mismatches)."""),
]
spec = {"wave": "w1", "milestone": "Round75 post-freeze: independent leg (b), leg (c) re-run, repetition, replay/limit attacks, sources re-open; 11 seats, 5 attack roles (3 reviewer, 1 critic, 1 mutation-tester) + revenger audit, L1 planner",
        "reportDir": ".ufo/waves/round-75/w1", "context": context, "items": items}
pathlib.Path(R + '/w1-spec.json').write_text(json.dumps(spec, indent=1, ensure_ascii=False) + "\n")
print(len(items), NA, NB)
